CREATE TYPE "TradeSide" AS ENUM ('BUY', 'SELL');
CREATE TYPE "TradeStatus" AS ENUM ('OPEN', 'CLOSED', 'SKIPPED');
CREATE TYPE "SettlementReason" AS ENUM ('SOURCE_SOLD', 'TAKE_PROFIT', 'STOP_LOSS', 'MANUAL', 'MAX_HOLDING_TIME', 'RISK_DETECTED');
CREATE TYPE "RiskLevel" AS ENUM ('SAFE', 'CAUTION', 'DANGEROUS');

CREATE TABLE "users" ("id" TEXT PRIMARY KEY, "wallet_address" TEXT UNIQUE, "display_name" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "tracked_wallets" ("id" TEXT PRIMARY KEY, "address" TEXT NOT NULL UNIQUE, "display_name" TEXT NOT NULL, "first_trade_at" TIMESTAMP(3) NOT NULL, "is_copy_enabled" BOOLEAN NOT NULL DEFAULT false, "is_blocked" BOOLEAN NOT NULL DEFAULT false, "risk_flags" TEXT[] DEFAULT ARRAY[]::TEXT[], "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "wallet_statistics" ("id" TEXT PRIMARY KEY, "wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id") ON DELETE CASCADE, "period_start" TIMESTAMP(3) NOT NULL, "period_end" TIMESTAMP(3) NOT NULL, "roi_30d" DECIMAL(12,4) NOT NULL, "realized_profit_usd" DECIMAL(20,6) NOT NULL, "realized_profit_sol" DECIMAL(20,9) NOT NULL, "unrealized_profit_usd" DECIMAL(20,6) NOT NULL, "unrealized_profit_sol" DECIMAL(20,9) NOT NULL, "win_rate" DECIMAL(8,4) NOT NULL, "average_roi" DECIMAL(12,4) NOT NULL, "average_win_rate" DECIMAL(12,4) NOT NULL, "average_loss_rate" DECIMAL(12,4) NOT NULL, "average_holding_sec" INTEGER NOT NULL, "max_drawdown" DECIMAL(12,4) NOT NULL, "trade_count" INTEGER NOT NULL, "sell_count" INTEGER NOT NULL, "profitable_trade_count" INTEGER NOT NULL, UNIQUE("wallet_id","period_start","period_end"));
CREATE TABLE "wallet_scores" ("id" TEXT PRIMARY KEY, "wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id") ON DELETE CASCADE, "calculated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "total" INTEGER NOT NULL, "roi_points" INTEGER NOT NULL, "realized_profit_points" INTEGER NOT NULL, "win_rate_points" INTEGER NOT NULL, "consistency_points" INTEGER NOT NULL, "drawdown_points" INTEGER NOT NULL, "trade_count_points" INTEGER NOT NULL, "age_points" INTEGER NOT NULL, "favorite_token_points" INTEGER NOT NULL, "penalty_points" INTEGER NOT NULL DEFAULT 0, "exclusion_reason" TEXT);
CREATE INDEX "wallet_scores_total_idx" ON "wallet_scores"("total");
CREATE TABLE "wallet_trades" ("id" TEXT PRIMARY KEY, "wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id") ON DELETE CASCADE, "signature" TEXT NOT NULL UNIQUE, "token_mint" TEXT NOT NULL, "token_symbol" TEXT, "side" "TradeSide" NOT NULL, "traded_at" TIMESTAMP(3) NOT NULL, "price_usd" DECIMAL(30,12) NOT NULL, "price_sol" DECIMAL(30,12) NOT NULL, "amount_token" DECIMAL(30,12) NOT NULL, "value_usd" DECIMAL(20,6) NOT NULL, "value_sol" DECIMAL(20,9) NOT NULL, "realized_pnl_usd" DECIMAL(20,6), "realized_pnl_sol" DECIMAL(20,9));
CREATE TABLE "wallet_holdings" ("id" TEXT PRIMARY KEY, "wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id") ON DELETE CASCADE, "token_mint" TEXT NOT NULL, "token_symbol" TEXT, "quantity" DECIMAL(30,12) NOT NULL, "average_cost_usd" DECIMAL(30,12) NOT NULL, "average_cost_sol" DECIMAL(30,12) NOT NULL, "current_value_usd" DECIMAL(20,6) NOT NULL, "current_value_sol" DECIMAL(20,9) NOT NULL, "updated_at" TIMESTAMP(3) NOT NULL, UNIQUE("wallet_id","token_mint"));
CREATE TABLE "favorite_tokens" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "symbol" TEXT NOT NULL, "token_mint" TEXT NOT NULL, "icon_url" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("user_id","token_mint"));
CREATE TABLE "favorite_token_wallets" ("id" TEXT PRIMARY KEY, "favorite_token_id" TEXT NOT NULL REFERENCES "favorite_tokens"("id") ON DELETE CASCADE, "wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id") ON DELETE CASCADE, "realized_profit_usd" DECIMAL(20,6) NOT NULL, "realized_profit_sol" DECIMAL(20,9) NOT NULL, "trade_count" INTEGER NOT NULL, "sell_count" INTEGER NOT NULL, UNIQUE("favorite_token_id","wallet_id"));
CREATE TABLE "copy_settings" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE CASCADE, "enabled" BOOLEAN NOT NULL DEFAULT true, "amount_per_trade_usd" DECIMAL(20,6) NOT NULL, "max_positions" INTEGER NOT NULL, "max_daily_amount_usd" DECIMAL(20,6) NOT NULL, "stop_loss_percent" DECIMAL(8,4) NOT NULL, "take_profit_percent" DECIMAL(8,4) NOT NULL, "max_slippage_percent" DECIMAL(8,4) NOT NULL, "max_wallets" INTEGER NOT NULL, "allow_duplicate_token" BOOLEAN NOT NULL DEFAULT false, "favorites_only" BOOLEAN NOT NULL DEFAULT false, "min_liquidity_usd" DECIMAL(20,6) NOT NULL, "min_market_cap_usd" DECIMAL(20,6) NOT NULL, "max_detection_seconds" INTEGER NOT NULL, "max_price_rise_percent" DECIMAL(8,4) NOT NULL, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "paper_positions" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "source_wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id"), "token_mint" TEXT NOT NULL, "token_symbol" TEXT NOT NULL, "source_bought_at" TIMESTAMP(3) NOT NULL, "copied_at" TIMESTAMP(3) NOT NULL, "detection_delay_ms" INTEGER NOT NULL, "source_price_usd" DECIMAL(30,12) NOT NULL, "copy_price_usd" DECIMAL(30,12) NOT NULL, "slippage_percent" DECIMAL(8,4) NOT NULL, "amount_usd" DECIMAL(20,6) NOT NULL, "amount_sol" DECIMAL(20,9) NOT NULL, "quantity" DECIMAL(30,12) NOT NULL, "status" "TradeStatus" NOT NULL DEFAULT 'OPEN', "closed_at" TIMESTAMP(3), "exit_price_usd" DECIMAL(30,12), "pnl_percent" DECIMAL(12,4), "pnl_usd" DECIMAL(20,6), "pnl_sol" DECIMAL(20,9), "settlement_reason" "SettlementReason");
CREATE TABLE "paper_trades" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "source_wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id"), "token_mint" TEXT NOT NULL, "token_symbol" TEXT NOT NULL, "side" "TradeSide" NOT NULL, "traded_at" TIMESTAMP(3) NOT NULL, "buy_price_usd" DECIMAL(30,12), "sell_price_usd" DECIMAL(30,12), "amount_usd" DECIMAL(20,6) NOT NULL, "amount_sol" DECIMAL(20,9) NOT NULL, "pnl_percent" DECIMAL(12,4), "pnl_usd" DECIMAL(20,6), "pnl_sol" DECIMAL(20,9), "settlement_reason" "SettlementReason");
CREATE TABLE "skipped_trades" ("id" TEXT PRIMARY KEY, "user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "source_wallet_id" TEXT NOT NULL REFERENCES "tracked_wallets"("id"), "token_mint" TEXT NOT NULL, "token_symbol" TEXT, "detected_at" TIMESTAMP(3) NOT NULL, "source_bought_at" TIMESTAMP(3) NOT NULL, "reason_code" TEXT NOT NULL, "reason_detail" TEXT, "signal_snapshot" JSONB NOT NULL);
CREATE TABLE "token_risk_checks" ("id" TEXT PRIMARY KEY, "token_mint" TEXT NOT NULL, "checked_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "risk_level" "RiskLevel" NOT NULL, "is_honeypot" BOOLEAN NOT NULL, "has_freeze_authority" BOOLEAN NOT NULL, "has_mint_authority" BOOLEAN NOT NULL, "liquidity_usd" DECIMAL(20,6) NOT NULL, "market_cap_usd" DECIMAL(20,6) NOT NULL, "flags" TEXT[] DEFAULT ARRAY[]::TEXT[], "raw_response" JSONB);
CREATE TABLE "system_logs" ("id" TEXT PRIMARY KEY, "level" TEXT NOT NULL, "service" TEXT NOT NULL, "event" TEXT NOT NULL, "message" TEXT NOT NULL, "metadata" JSONB, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
